cypress_script:
describe('Multi-level navigation menu', () => {
  it('should navigate to Sub Item when clicked', () => {
    cy.visit('https://demoqa.com/menu');
    cy.contains('Main Item 1').click();
    cy.contains('Sub Item').click();
    cy.url().should('include', '/menu');
  });

  it('should not change URL when clicking on Main Item 1', () => {
    cy.visit('https://demoqa.com/menu');
    cy.contains('Main Item 1').click();
    cy.url().should('include', '/menu');
    cy.contains('Main Item 1').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Multi-level navigation menu', () => {
  test('should navigate to Sub Item when clicked', async ({ page }) => {
    await page.goto('https://demoqa.com/menu');
    await page.click('text=Main Item 1');
    await page.click('text=Sub Item');
    await expect(page).toHaveURL(/.*menu/);
  });

  test('should not change URL when clicking on Main Item 1', async ({ page }) => {
    await page.goto('https://demoqa.com/menu');
    await page.click('text=Main Item 1');
    await expect(page).toHaveURL(/.*menu/);
    await expect(page.locator('text=Main Item 1')).toBeVisible();
  });
});
